import{_ as l,a8 as e,o as n,c as i,ah as s,K as t}from"./chunks/framework.D9VmMSku.js";import"./chunks/theme.7j9Y6pfQ.js";const P=JSON.parse('{"title":"马斯克五部工作法","description":"","frontmatter":{"title":"马斯克五部工作法","abstract":"马斯克第一性原理驱动的五步工作法——验证需求、删减流程、简化优化、加速迭代、最后自动化，用最少资源做最高效的事。","created":"2026-07-02T00:00:00.000Z","tags":["思维模型","效率","工程思维"],"type":"步骤操作","related":["[[📚 个人知识管理-MOC]]","[[300法则]]"],"reference":null,"category":["📚 个人知识管理","个人能力"]},"headers":[],"relativePath":"vault/Knowledge/Methods/马斯克五部工作法.md","filePath":"vault/Knowledge/Methods/马斯克五部工作法.md","lastUpdated":1790655645000}'),h={name:"vault/Knowledge/Methods/马斯克五部工作法.md"};function d(_,a,c,p,b,g){const r=e("NolebaseGitContributors"),o=e("NolebaseGitChangelog");return n(),i("div",null,[a[0]||(a[0]=s('<h1 id="马斯克五部工作法" tabindex="-1">马斯克五部工作法 <a class="header-anchor" href="#马斯克五部工作法" aria-label="Permalink to “马斯克五部工作法”">​</a></h1><h2 id="一句话概述" tabindex="-1">一句话概述 <a class="header-anchor" href="#一句话概述" aria-label="Permalink to “一句话概述”">​</a></h2><p>马斯克的第一性原理驱动的工作方法论——从本质出发，剔除一切非必要，用最少的资源做最高效的事。</p><h2 id="五步流程" tabindex="-1">五步流程 <a class="header-anchor" href="#五步流程" aria-label="Permalink to “五步流程”">​</a></h2><h3 id="_1-验证需求" tabindex="-1">1. 验证需求 <a class="header-anchor" href="#_1-验证需求" aria-label="Permalink to “1. 验证需求”">​</a></h3><p><strong>别让你的需求变得愚蠢。</strong> 无论是谁提出的需求，先追问「这个需求真的需要被满足吗？」——很多需求是伪需求，满足它们只是浪费资源。</p><h3 id="_2-最少流程" tabindex="-1">2. 最少流程 <a class="header-anchor" href="#_2-最少流程" aria-label="Permalink to “2. 最少流程”">​</a></h3><p><strong>删掉所有能删的步骤。</strong> 如果删完还得加回来不到 10%，说明删得还不够狠。先做最少必要步骤，拿到结果再决定要不要加。</p><h3 id="_3-简化和优化" tabindex="-1">3. 简化和优化 <a class="header-anchor" href="#_3-简化和优化" aria-label="Permalink to “3. 简化和优化”">​</a></h3><p><strong>先简化，再优化。</strong> 在完成前两步之前不要优化——优化一个本可以删掉的流程是最蠢的事。常见的反模式：给一个不必要存在的功能做性能优化。</p><h3 id="_4-加速迭代" tabindex="-1">4. 加速迭代 <a class="header-anchor" href="#_4-加速迭代" aria-label="Permalink to “4. 加速迭代”">​</a></h3><p><strong>让循环更快。</strong> 前三个步骤做得足够好后，加快每个迭代周期。快的试错 &gt; 慢的完美。</p><h3 id="_5-自动化" tabindex="-1">5. 自动化 <a class="header-anchor" href="#_5-自动化" aria-label="Permalink to “5. 自动化”">​</a></h3><p><strong>最后才自动化。</strong> 别在搞清楚流程之前就写脚本。自动化正确的流程是杠杆，自动化错误的流程是灾难。</p><h2 id="核心原则" tabindex="-1">核心原则 <a class="header-anchor" href="#核心原则" aria-label="Permalink to “核心原则”">​</a></h2><ul><li>始终从第一性原理出发，而非类比</li><li>删 &gt; 改 &gt; 加</li><li>先验证再投入</li></ul><h2 id="应用场景" tabindex="-1">应用场景 <a class="header-anchor" href="#应用场景" aria-label="Permalink to “应用场景”">​</a></h2><p>适用于产品设计、项目管理、个人效率优化——任何需要「做对的事，再把事做对」的场景。</p>',18)),t(r),t(o)])}const u=l(h,[["render",d]]);export{P as __pageData,u as default};
